23: const sortAlphaNum = ({ value: a }, { value: b }) => {
24:   const reA = /[^a-zA-Z]/g;
25:   const reN = /[^0-9]/g;
26:   const aA = a.replace(reA, "");
27:   const bA = b.replace(reA, "");
28:   if (aA === bA) {
29:     const aN = parseInt(a.replace(reN, ""), 10);
30:     const bN = parseInt(b.replace(reN, ""), 10);
31:     if (aN === bN) {
32:       return 0;
33:     }
34:     return aN > bN ? 1 : -1;
35:   }
36:   return aA > bA ? 1 : -1;
37: };
